// 18-tap FIR, TRANSPOSED direct form: one multiply + one add per stage, so the
// register-to-register critical path is independent of tap count -> high Fmax.
// Same transferfunction as the direct form (equivalent up to a fixed latency).
module firr18_v5 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg [23:0] a0, a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, a13, a14, a15, a16, a17;
    always @(posedge clk) begin
        if (!rst_n) begin
            a0 <= '0; a1 <= '0; a2 <= '0; a3 <= '0; a4 <= '0; a5 <= '0; a6 <= '0; a7 <= '0; a8 <= '0; a9 <= '0; a10 <= '0; a11 <= '0; a12 <= '0; a13 <= '0; a14 <= '0; a15 <= '0; a16 <= '0; a17 <= '0; y <= '0;
        end else begin
            a0 <= 8'd2 * x + 2'd3;
            a1 <= 8'd4 * $signed(a0[7:0]) + 2'd3;
            a2 <= 8'd6 * $signed(a1[7:0]) + 2'd3;
            a3 <= 8'd8 * $signed(a2[7:0]) + 2'd3;
            a4 <= 8'd10 * $signed(a3[7:0]) + 2'd3;
            a5 <= 8'd12 * $signed(a4[7:0]) + 2'd3;
            a6 <= 8'd14 * $signed(a5[7:0]) + 2'd3;
            a7 <= 8'd16 * $signed(a6[7:0]) + 2'd3;
            a8 <= 8'd18 * $signed(a7[7:0]) + 2'd3;
            a9 <= 8'd20 * $signed(a8[7:0]) + 2'd3;
            a10 <= 8'd22 * $signed(a9[7:0]) + 2'd3;
            a11 <= 8'd24 * $signed(a10[7:0]) + 2'd3;
            a12 <= 8'd26 * $signed(a11[7:0]) + 2'd3;
            a13 <= 8'd28 * $signed(a12[7:0]) + 2'd3;
            a14 <= 8'd30 * $signed(a13[7:0]) + 2'd3;
            a15 <= 8'd32 * $signed(a14[7:0]) + 2'd3;
            a16 <= 8'd34 * $signed(a15[7:0]) + 2'd3;
            a17 <= 8'd36 * $signed(a16[7:0]) + 2'd3;
            y <= a17[15:0];
        end
    end
endmodule
